"/Users/muskanpaliwal/Work/open-source/contribution-dashboard",
"/Users/muskanpaliwal/Work/open-source/entire/entire-lens/main",
"/Users/muskanpaliwal/Work/open-source/go-git-cli/main"
];
const results = await Promise.all(repos.map(repo => tools.exec_command({
  cmd: "bash /Users/muskanpaliwal/.codex/skills/hub/repository-bootstrap/scripts/repository-bootstrap check --repo . --format json",
  workdir: repo,
  yield_time_ms: 10000,
  max_output_tokens: 12000
})));
results.forEach((r,i) => { text(`REPO ${repos[i]}\n${r.output}\nEXIT ${r.exit_code}`); });

const repos = [
"/Users/muskanpaliwal/dotfiles",
"/Users/muskanpaliwal/notes",
"/Users/muskanpaliwal/Work/open-source/contribution-dashboard",
"/Users/muskanpaliwal/Work/open-source/entire/entire-lens/main",
"/Users/muskanpaliwal/Work/open-source/go-git-cli/main"
];
for (const repo of repos) {
  const r = await tools.exec_command({
    cmd: "git fetch --no-tags origin refs/heads/main:refs/remotes/origin/main",
    workdir: repo,
    yield_time_ms: 30000,
    max_output_tokens: 4000,
    sandbox_permissions: "require_escalated",
    justification: "Allow fetching origin/main in these MuskanPaliwal repositories so I can verify there is no divergence before the authorized direct main pushes?",
    prefix_rule: ["git", "fetch"]
  });
  text(`REPO ${repo}\n${r.output}\nEXIT ${r.exit_code}`);
}

const r = await tools.exec_command({
  cmd: "git fetch --no-tags origin refs/heads/main:refs/remotes/origin/main",
  workdir: "/Users/muskanpaliwal/Writings",
  yield_time_ms: 30000,
  max_output_tokens: 4000,
  sandbox_permissions: "require_escalated",
  justification: "Allow fetching origin/main in MuskanPaliwal/tech-journal so I can verify there is no divergence before the authorized direct main push?",
  prefix_rule: ["git", "fetch"]
});
text(r.output);
text(`EXIT ${r.exit_code}`);

const repos = [
"/Users/muskanpaliwal/dotfiles",
"/Users/muskanpaliwal/notes",
"/Users/muskanpaliwal/Work/open-source/contribution-dashboard",
"/Users/muskanpaliwal/Work/open-source/entire/entire-lens/main",
"/Users/muskanpaliwal/Work/open-source/go-git-cli/main",
"/Users/muskanpaliwal/Writings"
];
const results = await Promise.all(repos.map(repo => tools.exec_command({
  cmd: "git rev-list --left-right --count refs/remotes/origin/main...HEAD && git log -1 --format='%H %s' refs/remotes/origin/main && git log -1 --format='%H %s' HEAD",
  workdir: repo,
  yield_time_ms: 10000,
  max_output_tokens: 4000
})));
results.forEach((r,i) => text(`REPO ${repos[i]}\n${r.output}\nEXIT ${r.exit_code}`));

const repos = [
"/Users/muskanpaliwal/dotfiles",
"/Users/muskanpaliwal/notes",
"/Users/muskanpaliwal/Work/open-source/contribution-dashboard",
"/Users/muskanpaliwal/Work/open-source/entire/entire-lens/main",
"/Users/muskanpaliwal/Writings"
];
for (const repo of repos) {
  const r = await tools.exec_command({
    cmd: "shasum -a 256 .entire/runners/*.json",
    workdir: repo,
    yield_time_ms: 10000,
    max_output_tokens: 5000
  });
  text(`REPO ${repo}\n${r.output}`);
}

const r = await tools.exec_command({
  cmd: "for f in .entire/runners/*.json; do printf '\\nFILE %s\\n' \"$f\"; jq . \"$f\"; done",
  workdir: "/Users/muskanpaliwal/notes",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

